def _g(slug, title, level, category, summary, explanation, examples, rules=None):
    return GrammarTopic(slug=slug, title=title, level=level, category=category, summary=summary,
        explanation=explanation, rules=rules or [], examples=[GrammarExample(text=x) for x in examples])

