def _unit(level, n, title, grammar, vocab, checklist):
    return CurriculumUnit(id=f"uz-{level.lower()}-unit-{n}", level=level, unit_number=n, title=title,
        grammar_points=grammar, vocabulary_set_ids=vocab, lesson_types=["grammar","vocabulary","listening","speaking","reading","writing"],
        competency_checklist=checklist, default_weeks=2)

